"""
Handles lazy initialization of static fields.

`_globalGetters` and `_globalSetters`: when a global is read from a module other than the module
defining it, they map the global to the getter (setter) function defined and exported in the
defining module.
"""
@parity "dart2wasm/lib/globals.dart:20 Globals" struct Globals
    translator::KernelNodes
    _global_getters::LinkedHashMap{WasmBuilder.IR.Global,WasmBuilder.IR.BaseFunction}
    _global_setters::LinkedHashMap{WasmBuilder.IR.Global,WasmBuilder.IR.BaseFunction}
    _globals_module_map::WasmGlobalImporter
    # the struct's one constructor, tagged; dart's constructor at :31 is its outer function
    Globals(::Val{:_}, translator::KernelNodes, _globals_module_map::WasmGlobalImporter) =
        new(translator, LinkedHashMap{WasmBuilder.IR.Global,WasmBuilder.IR.BaseFunction}(),
            LinkedHashMap{WasmBuilder.IR.Global,WasmBuilder.IR.BaseFunction}(), _globals_module_map)
end

"""
The Wasm globals and table slots of the program's static fields: dart's static `Field`s are Julia's
global bindings, each named by its `GlobalRef`, and `_fieldTypeCount` counts the bindings of each
wasm type.
"""
@parity "dart2wasm/lib/globals.dart:91 DartGlobals" struct DartGlobals
    translator::KernelNodes
    _field_type_count::Dict{WasmBuilder.IR.ValueType,Int}
    _definitions::Dict{GlobalRef,DartGlobalDefinition}
    # the struct's one constructor, tagged; dart's constructor at :97 is its outer function, which
    # counts the fields
    DartGlobals(::Val{:_}, translator::KernelNodes) =
        new(translator, Dict{WasmBuilder.IR.ValueType,Int}(), Dict{GlobalRef,DartGlobalDefinition}())
end

