"""
If we have more than this number of fields of the same type, we prefer using a wasm table to hold
field values over globals.
"""
@parity "dart2wasm/lib/globals.dart:17 dartFieldTableUseCutoff" dart_field_table_use_cutoff()::Int = 10

@parity "dart2wasm/lib/globals.dart:31 Globals" Globals(translator::KernelNodes)::Globals = Globals(Val(:_), translator, WasmGlobalImporter(translator, "global"))

"""
Reads the value of `global_` onto the stack in `b`.

Takes into account the calling module and the module the global belongs to. If they are not the
same then accesses the global indirectly, either through an import or a getter call.
"""
@parity "dart2wasm/lib/globals.dart:39 Globals.readGlobal" function read_global(self::Globals, b::WasmBuilder.InstructionsBuilder, global_::WasmBuilder.IR.Global)::WasmBuilder.IR.ValueType
    local owning_module = get(self.translator.module_to_builder, global_.enclosing_module, nothing)
    owning_module === nothing && reject!(Internal("dart2wasm/lib/globals.dart:40 Globals.readGlobal: the module of $global_ has no builder"), "Globals.readGlobal")
    local calling_module = b.module_builder
    if owning_module === calling_module
        WasmBuilder.global_get(b, global_)
    elseif is_main_module(self.translator, owning_module)
        local imported_global = get(self._globals_module_map, global_, calling_module)
        WasmBuilder.global_get(b, imported_global)
    else
        local getter = get(self._global_getters, global_, nothing)
        if getter === nothing
            local getter_type = WasmBuilder.define_function(owning_module.types[], WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[global_.type.type])
            local getter_function = WasmBuilder.define(owning_module.functions[], getter_type)
            getter_function.is_pure = true
            local getter_body = WasmBuilder.body(getter_function)
            WasmBuilder.global_get(getter_body, global_)
            WasmBuilder.var"end"(getter_body)
            getter = self._global_getters[global_] = getter_function
        end
        call_function(self.translator, getter, b)
    end
    return global_.type.type
end

"""Dual to [`read_global`](@ref)."""
@parity "dart2wasm/lib/globals.dart:66 Globals.writeGlobal" function write_global(self::Globals, b::WasmBuilder.InstructionsBuilder, global_::WasmBuilder.IR.Global)::Nothing
    local owning_module = get(self.translator.module_to_builder, global_.enclosing_module, nothing)
    owning_module === nothing && reject!(Internal("dart2wasm/lib/globals.dart:67 Globals.writeGlobal: the module of $global_ has no builder"), "Globals.writeGlobal")
    local calling_module = b.module_builder
    if owning_module === calling_module
        WasmBuilder.global_set(b, global_)
    elseif is_main_module(self.translator, owning_module)
        local imported_global = get(self._globals_module_map, global_, calling_module)
        WasmBuilder.global_set(b, imported_global)
    else
        local setter = get(self._global_setters, global_, nothing)
        if setter === nothing
            local setter_type = WasmBuilder.define_function(owning_module.types[], WasmBuilder.IR.ValueType[global_.type.type], WasmBuilder.IR.ValueType[])
            local setter_function = WasmBuilder.define(owning_module.functions[], setter_type)
            local setter_body = WasmBuilder.body(setter_function)
            WasmBuilder.local_get(setter_body, only(WasmBuilder.locals(setter_function)))
            WasmBuilder.global_set(setter_body, global_)
            WasmBuilder.var"end"(setter_body)
            setter = self._global_setters[global_] = setter_function
        end
        call_function(self.translator, setter, b)
    end
    return nothing
end

"""
Counts the program's static fields of each wasm type. dart counts every static field of every
library; a Julia program's static fields are the global bindings the closed world reads (each
`GlobalRef` of its NIR, an operand (nir_operands) or a statement), but a binding of a function, a type or a module,
which declare Julia's methods, classes and modules as dart's procedures, classes and libraries do.
"""
@parity "dart2wasm/lib/globals.dart:97 DartGlobals" function DartGlobals(translator::Translator)::DartGlobals
    local self = DartGlobals(Val(:_), translator)
    local seen = Set{GlobalRef}()
    local count(ref::GlobalRef) = begin
        ref in seen && return nothing
        push!(seen, ref)
        isdefinedglobal(ref.mod, ref.name) && getglobal(ref.mod, ref.name) isa Union{Function,Type,Module} && return nothing
        local wasm_type = translate_type_of_field(translator, ref)
        self._field_type_count[wasm_type] = get(self._field_type_count, wasm_type, 0) + 1
        return nothing
    end
    for body in translator.component, st in body.stmts
        st isa NirGlobalRead && count(st.ref)
        for v in nir_operands(st)
            v isa NirGlobal && count(v.ref)
        end
    end
    return self
end

"""
dart's literal initializer of a static field, its constant. A Julia global binding has no
initializer expression: a juliac image is the heap after the top level ran, but every module's
`__init__` runs again at load (Julia 1.13 Compiler/src/precompile.jl:352-366), so a value set or
mutated at load is no build-time constant. A binding's value is its constant initializer only when no
load can change it: the binding is `const` and its value is free of mutation (`Base.ismutationfree`
of its type), the NIR's literal of it, compared by `===`. Every other binding (a non-const one, one
`__init__` assigns, a const one holding a mutable object, one with no value) has none and takes
dart's lazy path.

A deliberate difference from dart, whose initializer is the field's literal expression.
"""
@parity "dart2wasm/lib/globals.dart:113 DartGlobals.getConstantInitializer" function get_constant_initializer(self::DartGlobals, variable::GlobalRef)::Union{NirConst,Nothing}
    isdefinedglobal(variable.mod, variable.name) && isconst(variable.mod, variable.name) || return nothing
    local value = getglobal(variable.mod, variable.name)
    Base.ismutationfree(typeof(value)) || return nothing
    return NirConst(Core.Const(value))
end

"""
Return (and if needed create) the Wasm global corresponding to a static field, a Julia global
binding. Julia has no late static fields; a binding's module is the main module (deferred loading is
out of scope); a binding is final when it is `const`. A binding has no initializer expression, so
the start-function path (dart's `field.initializer != null`) is taken only by the pragma, which no
binding carries; and the lazy path, dart's static field initializer function, is the binding's
module's top level or `__init__`, which the closed world does not compile: it rejects, located,
until that path is ported.
"""
@parity "dart2wasm/lib/globals.dart:126 DartGlobals.getDefinitionForStaticField" function get_definition_for_static_field(self::DartGlobals, field::GlobalRef)::DartGlobalDefinition
    local existing = get(self._definitions, field, nothing)
    existing === nothing || return existing
    local translator = self.translator
    local field_type = translate_type_of_field(translator, field)
    local number_of_fields_with_same_type = get(self._field_type_count, field_type, nothing)
    number_of_fields_with_same_type === nothing &&
        reject!(Internal("dart2wasm/lib/globals.dart:131 DartGlobals.getDefinitionForStaticField: the binding $field is no static field the closed world reads"), "DartGlobals.getDefinitionForStaticField")
    local use_table_slot = number_of_fields_with_same_type >= dart_field_table_use_cutoff() && field_type isa WasmBuilder.IR.RefType

    local module_ = main_module(translator)

    # If the initializer expression is a constant expression then the field
    # doesn't have to become lazy.
    #
    # If the type is non-nullable we prefer to use a global as using a table
    # can cause null checks on usages. Oterhwise we use [useTableSlot]
    # heuristic to determine whether to use a table or not.
    local init = get_constant_initializer(self, field)
    if init !== nothing && try_instantiate_eagerly_from(translator.constants[], module_, init, field_type)
        if use_table_slot && WasmBuilder.nullable(field_type)
            return self._definitions[field] = _define_table_based_field(self, field, field_type::WasmBuilder.IR.RefType, module_, init, nothing)
        end
        return self._definitions[field] = _define_global_based_field(self, field, field_type, module_, !isconst(field.mod, field.name), init, nothing)
    end

    # Maybe we can emit the initialization in the start function. If so,
    # that's preferred as we don't need to pay for lazy-init check on each
    # access.
    if _initialize_at_startup(self, field)
        local definition = _define_global_based_field(self, field, field_type, module_, true, init, nothing)

        # We have to initialize the global field in the same module as where
        # the field value is defined in.
        generate(EagerStaticFieldInitializerCodeGenerator(translator, field, definition.global_),
            WasmBuilder.body(WasmBuilder.start_function(module_)), WasmBuilder.IR.Local[], nothing)

        return self._definitions[field] = definition
    end

    # Add initializer function to the compilation queue: a binding's initializer is its module's top
    # level or __init__, which the closed world does not compile.
    reject!(Unquarantined("src/globals.jl getDefinitionForStaticField: the binding $field, with no build-time constant, whose initializer the closed world does not compile"), "DartGlobals.getDefinitionForStaticField")
end

@parity "dart2wasm/lib/globals.dart:225 DartGlobals._defineInitializerFlag" function _define_initializer_flag(self::DartGlobals, field::GlobalRef, module_::WasmBuilder.ModuleBuilder)::WasmBuilder.GlobalBuilder
    local member_name = _member_name(self, field)
    local global_ = WasmBuilder.define(module_.globals[], WasmBuilder.IR.GlobalType(WasmBuilder.IR.NumType_i32), "$member_name initialized")
    WasmBuilder.i32_const(global_.initializer, 0)
    WasmBuilder.var"end"(global_.initializer)
    return global_
end

@parity "dart2wasm/lib/globals.dart:236 DartGlobals._defineTableBasedField" function _define_table_based_field(self::DartGlobals, field::GlobalRef, field_type::WasmBuilder.IR.RefType, module_::WasmBuilder.ModuleBuilder,
        init::Union{NirConst,Nothing}, initializer_flag::Union{Nothing,WasmBuilder.GlobalBuilder})::TableBasedDartGlobal
    local table = get_table_for_type(self.translator.table_based_globals[], field_type.heap_type)
    # dart's NullConstant is Julia's nothing, the one value of Nothing
    if init !== nothing && init.c.val !== nothing
        return TableBasedDartGlobal(table, index_for_object(table, field, module_, function (ib::WasmBuilder.InstructionsBuilder)
            instantiate_constant(self.translator.constants[], ib, init, field_type)
            WasmBuilder.var"end"(ib)
        end))
    end
    return TableBasedDartGlobal(table, index_for_object(table, field); initialized_flag = initializer_flag)
end

@parity "dart2wasm/lib/globals.dart:262 DartGlobals._defineGlobalBasedField" function _define_global_based_field(self::DartGlobals, field::GlobalRef, field_type::WasmBuilder.IR.ValueType, module_::WasmBuilder.ModuleBuilder,
        mutable_::Bool, init::Union{NirConst,Nothing}, initializer_flag::Union{Nothing,WasmBuilder.GlobalBuilder})::WasmGlobalDartGlobal
    local member_name = _member_name(self, field)
    local global_ = WasmBuilder.define(module_.globals[], WasmBuilder.IR.GlobalType(field_type; mutable = mutable_), member_name)
    if init !== nothing
        instantiate_constant(self.translator.constants[], global_.initializer, init, field_type)
    else
        instantiate_local_dummy_value(get_dummy_values_collector_for_module(self.translator, module_), global_.initializer, field_type)
    end
    WasmBuilder.var"end"(global_.initializer)
    return WasmGlobalDartGlobal(global_; initialized_flag = initializer_flag)
end

# dart's `field.toString()`, a member's qualified name; a Julia binding's is its GlobalRef's, `Module.name`
@parity "dart2wasm/lib/globals.dart:290 DartGlobals._memberName" _member_name(self::DartGlobals, field::GlobalRef)::String = string(field)

"""
dart's `wasm:initialize-at-startup` pragma: `getPragma(..., defaultValue: true) ?? false`, whose
default applies only to a pragma present without a value, so a field with no pragma answers `false`
(util.dart:64 returns null). Julia declares no pragmas, so every binding answers `false` and is
initialized lazily.
"""
@parity "dart2wasm/lib/globals.dart:292 DartGlobals._initializeAtStartup" _initialize_at_startup(self::DartGlobals, node::GlobalRef)::Bool = false

# dart's sealed class is abstract: its constructor runs only as a subclass's super constructor, whose
# struct holds its field; called on its own it is dart's compile error
@parity "dart2wasm/lib/globals.dart:304 DartGlobalDefinition" function DartGlobalDefinition(; initialized_flag::Union{WasmBuilder.IR.Global,Nothing} = nothing)::Union{}
    reject!(Internal("dart2wasm/lib/globals.dart:304 DartGlobalDefinition: the sealed class is constructed only through a subclass"), "DartGlobalDefinition")
end

