@parity "dart2wasm/lib/globals.dart:320 WasmGlobalDartGlobal.type" type(self::WasmGlobalDartGlobal)::WasmBuilder.IR.ValueType = self.global_.type.type

@parity "dart2wasm/lib/globals.dart:323 WasmGlobalDartGlobal.read" Base.read(self::WasmGlobalDartGlobal, translator::Translator, b::WasmBuilder.InstructionsBuilder)::WasmBuilder.IR.ValueType =
    read_global(translator.globals[], b, self.global_)

@parity "dart2wasm/lib/globals.dart:328 WasmGlobalDartGlobal.write" function Base.write(self::WasmGlobalDartGlobal, translator::Translator, b::WasmBuilder.InstructionsBuilder, push_value::Function)::Nothing
    push_value(b)
    write_global(translator.globals[], b, self.global_)
    return nothing
end

@parity "dart2wasm/lib/globals.dart:342 TableBasedDartGlobal" TableBasedDartGlobal(table::TypeSpecificGlobalTable, index::Int; initialized_flag::Union{WasmBuilder.IR.Global,Nothing} = nothing)::TableBasedDartGlobal =
