@parity "dart2wasm/lib/globals.dart:345 TableBasedDartGlobal.type" type(self::TableBasedDartGlobal)::WasmBuilder.IR.ValueType = type(self.table)

@parity "dart2wasm/lib/globals.dart:348 TableBasedDartGlobal.read" function Base.read(self::TableBasedDartGlobal, translator::Translator, b::WasmBuilder.InstructionsBuilder)::WasmBuilder.IR.RefType
    local wasm_table = get_wasm_table(self.table, b.module_builder)
    WasmBuilder.i32_const(b, self.index)
    WasmBuilder.table_get(b, wasm_table)
    return wasm_table.type
end

@parity "dart2wasm/lib/globals.dart:356 TableBasedDartGlobal.write" function Base.write(self::TableBasedDartGlobal, translator::Translator, b::WasmBuilder.InstructionsBuilder, push_value::Function)::Nothing
    WasmBuilder.i32_const(b, self.index)
    push_value(b)
    WasmBuilder.table_set(b, get_wasm_table(self.table, b.module_builder))
    return nothing
end
